import java.io.*;

public class Main {

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int N = nextInt(in);

        int[] head = new int[N + 1];
        int[] nxt = new int[2 * (N - 1)];
        int[] to = new int[2 * (N - 1)];
        int idx = 0;

        // head[u] = -1 means no edges yet
        for (int i = 0; i < N + 1; i++) head[i] = -1;

        for (int i = 0; i < N - 1; i++) {
            int a = nextInt(in);
            int b = nextInt(in);
            to[idx] = b; nxt[idx] = head[a]; head[a] = idx; idx++;
            to[idx] = a; nxt[idx] = head[b]; head[b] = idx; idx++;
        }

        // Iterative DFS to get traversal order and parents (avoids stack overflow)
        int[] parent = new int[N + 1];
        int[] order = new int[N];
        boolean[] visited = new boolean[N + 1];
        int[] stack = new int[N];
        int top = 0, cnt = 0;

        stack[top++] = 1;
        visited[1] = true;
        parent[1] = 0;

        while (top > 0) {
            int u = stack[--top];
            order[cnt++] = u;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    stack[top++] = v;
                }
            }
        }

        // Compute subtree sizes in reverse DFS order
        int[] size = new int[N + 1];
        for (int i = 1; i <= N; i++) size[i] = 1;

        int best = Integer.MAX_VALUE;
        for (int i = N - 1; i >= 1; i--) {
            int u = order[i];
            size[parent[u]] += size[u];
            // Removing edge (parent[u], u) splits tree into size[u] and N - size[u]
            int diff = Math.abs(N - 2 * size[u]);
            if (diff < best) best = diff;
        }

        StringBuilder sb = new StringBuilder();
        sb.append(best).append('\n');
        System.out.print(sb);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b;
        boolean neg = false;
        do {
            b = in.read();
        } while (b != '-' && (b < '0' || b > '9'));
        if (b == '-') {
            neg = true;
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return neg ? -ret : ret;
    }
}
